installer-gui-script:
    Cueline









function checkOS() {
    if (system.compareVersions(system.version.ProductVersion, '12.0') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'macOS 12 or later is required';
        my.result.message = 'Cueline needs macOS Monterey 12 or later.';
        return false;
    }
    return true;
}
// a model's files are all in Cueline's models folder already
function have(files) {
    var dir = (system.env.HOME || '') + '/Library/Application Support/Cueline/models/';
    for (var i = 0; i < files.length; i++) if (!system.files.fileExistsAtPath(dir + files[i])) return false;
    return true;
}


